// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Deploy and get initial totalSupply
        uint256 initialSupply = c.totalSupply();
        // Call mintSynth with address(0) as pool (not curated, but just to trigger _mint)
        // Use vm.prank to call from address(this) which is the deployer, bypass onlyPool
        vm.prank(address(this));
        c.mintSynth(address(this), 1000);
        // Now call allowance to trigger burnFrom internally (if any) - but allowance is a view function
        // Instead, call burnFrom to trigger _burn
        // But we need to set allowance first
        uint256 amount = 1000;
        c.approve(address(this), amount);
        vm.prank(address(this));
        // Calling burnFrom will call _burn internally
        c.burnFrom(address(this), amount);
        uint256 finalSupply = c.totalSupply();
        // Reference: totalSupply decreases by amount (1000 -> 0)
        // Bug: totalSupply increases by amount (1000 -> 2000)
        // Assert: reference holds (finalSupply == initialSupply), bug breaks (finalSupply != initialSupply)
        assertTrue(finalSupply == initialSupply, "totalSupply should remain unchanged after burnFrom");
    }
}

